<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import { damageResult, healthPenalty, opposedResult } from '../rules/rulesEngine'
import { attributes } from '../data/bramble'
import { loreSpells } from '../data/magicOptions'
import { spellDetails } from '../data/magicDetails'
import { ruleSourceDocuments } from '../data/rulesSource'
import { loadCharacters, type CharacterRecord, type PurchasedEquipment } from '../services/characters'
import { loadEncounters, writeEncounters, type EncounterRecord } from '../services/encounters'

const route=useRoute(),router=useRouter()
const encounters=ref<EncounterRecord[]>(loadEncounters())
const characters=ref<CharacterRecord[]>(loadCharacters().filter(c=>!c.draft))
const encounter=computed(()=>encounters.value.find(e=>e.id===String(route.params.id||''))||null)
const character=computed(()=>encounter.value?characters.value.find(c=>c.id===encounter.value?.characterId)||null:null)
function stamp(){return new Date().toISOString()} function persist(){writeEncounters(encounters.value)}
function attr(key:'agility'|'might'|'hide'|'lore'|'bravery'){return Number(character.value?.attributes?.[key]||0)}
function mod(key:'agility'|'might'|'hide'|'lore'|'bravery'){return attr(key)*2}
const gearGuts=computed(()=>Math.max(0,...(character.value?.equipment||[]).map(i=>{const m=String(i.detail||'').match(/Guts Bonus\s*\+?(\d+)/i);return m?Number(m[1]):0})))
const secondary=computed(()=>({speed:2+attr('agility'),aim:attr('agility')*2,mettle:attr('might')*2,ward:attr('hide')*2,control:attr('lore')*2,power:attr('might'),guts:attr('hide')+gearGuts.value}))
const magicLevel=computed(()=>Number(character.value?.magicLevel??(character.value?.path==='magic'?1:0)))
const manaRegen=computed(()=>2+magicLevel.value)
const skills=computed(()=>Object.entries(character.value?.skillRanks||{}).sort(([a],[b])=>a.localeCompare(b)))
const weapons=computed(()=>(character.value?.equipment||[]).filter(i=>i.category==='Weapon'))
const armor=computed(()=>(character.value?.equipment||[]).filter(i=>i.category==='Armor & Shield'))
const otherGear=computed(()=>(character.value?.equipment||[]).filter(i=>i.category!=='Weapon'&&i.category!=='Armor & Shield'))
const spells=computed(()=>{const c=character.value;if(!c)return[];const sig=c.loreAttunement?loreSpells[c.loreAttunement]?.[0]:'';return Array.from(new Set([sig,...(c.spells||[]),...(c.invocationSpells||[]),c.invocationSpell||''].filter(Boolean) as string[]))})
const talentSections=ruleSourceDocuments.talents.sections.filter(s=>s.heading!=='Overview'&&s.heading!=='TALENTS'&&!s.heading.startsWith('KEYWORDS'))
function talentText(name:string){return talentSections.find(s=>s.heading===name)?.blocks.filter(b=>b.type==='paragraph').map(b=>b.type==='paragraph'?b.text:'').join(' ')||''}
function event(text:string){const e=encounter.value;if(!e)return;e.events=[`${new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})} — ${text}`,...e.events].slice(0,50);e.lastResult=text;e.updatedAt=stamp();persist()}
const health=computed({get:()=>encounter.value?.health??30,set:(v:number)=>{if(!encounter.value)return;encounter.value.health=Math.max(0,Number(v||0));encounter.value.updatedAt=stamp();persist()}})
const mana=computed({get:()=>encounter.value?.mana??0,set:(v:number)=>{if(!encounter.value)return;encounter.value.mana=Math.max(0,Number(v||0));encounter.value.updatedAt=stamp();persist()}})
const fate=computed({get:()=>encounter.value?.fateMarks??0,set:(v:number)=>{if(!encounter.value)return;encounter.value.fateMarks=Math.max(0,Math.min(3,Number(v||0)));encounter.value.updatedAt=stamp();persist()}})
function changeRound(d:number){if(!encounter.value)return;const before=encounter.value.round;encounter.value.round=Math.max(1,encounter.value.round+d);if(encounter.value.round>before){mana.value+=manaRegen.value;event(`Round ${encounter.value.round}: +${manaRegen.value} Mana restored.`);resetAbilities()}else persist()}
const abilitySpent=reactive({instinct:false,movement:false,combat:false,reaction:false});const abilityTypes=['instinct','movement','combat','reaction'] as const
function resetAbilities(){abilityTypes.forEach(t=>abilitySpent[t]=false)}
const abilityStatus=computed(()=>abilityTypes.every(t=>abilitySpent[t])?'No Root ability types remain this round.':`${abilityTypes.filter(t=>!abilitySpent[t]).length} Root ability types available.`)
function die(){const a=new Uint32Array(1);crypto.getRandomValues(a);return(a[0]%10)+1} function dice(){return[die(),die(),die()]}
const rollResult=ref<{label:string;dice:number[];bonus:number;total:number}|null>(null)
function roll(label:string,bonus:number){const d=dice(),total=d.reduce((a,b)=>a+b,0)+bonus;rollResult.value={label,dice:d,bonus,total};event(`${label}: ${d.join(' + ')} + ${bonus} = ${total}.`)}
const targetWard=ref(18),strikeConditions=ref(0),wardConditions=ref(0),combatResult=ref<ReturnType<typeof opposedResult>|null>(null),activeWeapon=ref('')
function weaponType(i:PurchasedEquipment){return /projectile|thrown|bow|crossbow|sling|dart|blowpipe/i.test(`${i.name} ${i.detail||''}`)?'ranged':'melee'}
function attack(i:PurchasedEquipment){const type=weaponType(i);const stat=type==='ranged'?secondary.value.aim:secondary.value.mettle;combatResult.value=opposedResult(dice(),stat,strikeConditions.value,dice(),Number(targetWard.value||0),wardConditions.value);activeWeapon.value=i.name;abilitySpent.combat=true;event(`${i.name}: ${combatResult.value.hit?'Hit':'Miss'} — Strike ${combatResult.value.strike.total}, Ward ${combatResult.value.ward.total}.`)}
function weaponProfile(i:PurchasedEquipment){const d=String(i.detail||'').split('·').map(x=>x.trim());return{damage:d[0]||'—',weight:d[1]||'—',keywords:d.slice(2).join(' · ')||'—'}}
const selectedSpell=ref('')
function castSpell(name:string){const detail=spellDetails[name];const base=detail?.manaCost??0;const cost=Math.max(0,Number(base||0)-(detail?.lore===character.value?.loreAttunement?2:0));if(cost>mana.value){alert('Not enough Mana.');return}mana.value-=cost;selectedSpell.value=name;event(`Cast ${name} for ${cost} Mana.`)}
const damage=ref(8),damageType=ref<'standard'|'direct'|'lethal'>('standard'),damageConditions=ref(0)
const damageCalc=computed(()=>damageResult(damage.value,damageType.value,attr('hide'),gearGuts.value,damageConditions.value))
function applyDamage(){health.value=Math.max(0,health.value-damageCalc.value.suffered);event(`${damageCalc.value.suffered} ${damageType.value} damage suffered.`)}
function complete(){if(!encounter.value)return;encounter.value.status='completed';encounter.value.updatedAt=stamp();persist();void router.push('/simulator')}
function toggleLock(){if(!encounter.value)return;encounter.value.locked=!encounter.value.locked;encounter.value.updatedAt=stamp();persist()}
function remove(){if(!encounter.value||!confirm('Delete this encounter?'))return;encounters.value=encounters.value.filter(e=>e.id!==encounter.value?.id);persist();void router.push('/simulator')}
const healthPenaltyValue=computed(()=>healthPenalty(health.value))
</script>
<template>
<main class="page encounter-page"><AppHeader compact back-to="/simulator" back-label="Back to Rhythm Engine" prefer-back-to />
<template v-if="encounter&&character">
<nav class="rule-breadcrumb"><RouterLink to="/simulator">Rhythm Engine</RouterLink><span>›</span><strong>Combat Encounter</strong></nav>
<div class="encounter-heading"><div><h1>{{ encounter.name }}</h1><p>{{ character.name }} · {{ character.species }}<template v-if="character.campaignName"> · {{ character.campaignName }}</template></p></div><div class="round-control"><button @click="changeRound(-1)">−</button><span><small>ROUND</small><strong>{{ encounter.round }}</strong></span><button @click="changeRound(1)">+</button></div></div>
<section class="core-abilities-sheet card-surface"><header><h2>Core Abilities</h2><span>{{ abilityStatus }}</span></header><p>Resolve start-of-turn triggers first. A character can use one Root Instinct, Movement, Combat, and Reaction per round. Passive abilities remain available whenever their trigger and restrictions are met.</p><div class="ability-cells"><button v-for="type in abilityTypes" :key="type" :class="{spent:abilitySpent[type]}" @click="abilitySpent[type]=!abilitySpent[type]"><span>Root {{ type }}</span><strong>{{ abilitySpent[type]?'Used':'Available' }}</strong></button><div><span>Passive</span><strong>Trigger Based</strong></div></div></section>
<section class="paper-character-sheet card-surface">
<header class="paper-sheet-header"><div><small>CHARACTER</small><h2>{{ character.name }}</h2><p>{{ character.species }} · {{ character.homeland }} · {{ character.path==='magic'?`Magic Level ${magicLevel}`:'Gifted Heart' }}</p></div><div class="paper-vitals"><label>Health<input v-model.number="health" type="number" /></label><label>Mana<input v-model.number="mana" type="number" /></label><label>Fate<input v-model.number="fate" type="number" /></label></div></header>
<div class="paper-sheet-section"><h3>Attributes</h3><div class="paper-stat-row"><button v-for="a in attributes" :key="a.id" @click="roll(`${a.name} Save`,mod(a.id))"><span>{{ a.name }}</span><strong>{{ character.attributes[a.id] }}</strong><small>Mod +{{ mod(a.id) }}</small></button></div></div>
<div class="paper-sheet-section"><h3>Secondary Stats</h3><div class="paper-stat-row secondary"><button @click="roll('Initiative',secondary.speed)"><span>Speed</span><strong>{{ secondary.speed }}</strong></button><button @click="roll('Aim',secondary.aim)"><span>Aim</span><strong>{{ secondary.aim }}</strong></button><button @click="roll('Mettle',secondary.mettle)"><span>Mettle</span><strong>{{ secondary.mettle }}</strong></button><button @click="roll('Ward',secondary.ward)"><span>Ward</span><strong>{{ secondary.ward }}</strong></button><button @click="roll('Control',secondary.control)"><span>Control</span><strong>{{ secondary.control }}</strong></button><div><span>Power</span><strong>{{ secondary.power }}</strong></div><div><span>Guts</span><strong>{{ secondary.guts }}</strong></div></div></div>
<div v-if="rollResult" class="paper-roll-strip"><strong>{{ rollResult.label }}: {{ rollResult.total }}</strong><span>{{ rollResult.dice.join(' + ') }} + {{ rollResult.bonus }}</span></div>
<div class="paper-sheet-columns">
<section><h3>Weapons</h3><div class="paper-box-list"><button v-for="weapon in weapons" :key="weapon.name" class="paper-entry weapon" :class="{active:activeWeapon===weapon.name}" @click="attack(weapon)"><header><strong>{{ weapon.name }}</strong><span>{{ weaponType(weapon)==='ranged'?'Ranged':'Melee' }}</span></header><div class="weapon-line"><span>Damage <b>{{ weaponProfile(weapon).damage }}</b></span><span>Weight <b>{{ weaponProfile(weapon).weight }}</b></span></div><p>{{ weaponProfile(weapon).keywords }}</p></button><p v-if="!weapons.length" class="muted">No weapons recorded.</p></div><div class="attack-target-fields"><label>Target Ward<input v-model.number="targetWard" type="number" /></label><label>Your Conditions<input v-model.number="strikeConditions" type="number" /></label><label>Ward Conditions<input v-model.number="wardConditions" type="number" /></label></div><div v-if="combatResult" class="combat-result-strip" :class="combatResult.hit?'good':'bad'"><strong>{{ combatResult.hit?'HIT':'MISS' }}</strong><span>Strike {{ combatResult.strike.total }} · Ward {{ combatResult.ward.total }}</span></div></section>
<section><h3>Armor &amp; Protection</h3><div class="paper-box-list"><article v-for="item in armor" :key="item.name" class="paper-entry armor"><header><strong>{{ item.name }}</strong></header><p>{{ item.detail }}</p></article><p v-if="!armor.length" class="muted">No armor or shields recorded.</p></div><div class="damage-line"><label>Incoming Damage<input v-model.number="damage" type="number" /></label><label>Type<select v-model="damageType"><option value="standard">Standard</option><option value="direct">Direct</option><option value="lethal">Lethal</option></select></label><label>Conditions<input v-model.number="damageConditions" type="number" /></label><div><span>Effective Guts</span><strong>{{ damageCalc.guts }}</strong></div><div><span>Health Lost</span><strong>{{ damageCalc.suffered }}</strong></div><button class="secondary-button" @click="applyDamage">Apply Damage</button></div></section>
</div>
<div class="paper-sheet-section"><h3>Skills</h3><div class="paper-skill-grid"><article v-for="([name,rank]) in skills" :key="name"><strong>{{ name }}</strong><span>Rank {{ rank }}</span><small>Modifier +{{ Number(rank)*2 }}</small></article></div></div>
<div class="paper-sheet-columns"><section><h3>Talents</h3><div class="paper-box-list"><article v-for="talent in character.talents||[]" :key="talent" class="paper-entry talent"><header><strong>{{ talent }}</strong></header><p>{{ talentText(talent) }}</p></article><p v-if="!character.talents?.length" class="muted">No Talents recorded.</p></div></section><section><h3>Magic &amp; Spells</h3><article v-if="character.path==='magic'" class="paper-entry lore"><header><strong>Lore of {{ character.loreAttunement }}</strong><span>+{{ manaRegen }} Mana/round</span></header></article><div class="paper-box-list"><button v-for="spell in spells" :key="spell" class="paper-entry spell" @click="castSpell(spell)"><header><strong>{{ spell }}</strong><span>{{ spellDetails[spell]?.manaCost===null?'Variable':`${Math.max(0,Number(spellDetails[spell]?.manaCost||0)-(spellDetails[spell]?.lore===character.loreAttunement?2:0))} Mana` }}</span></header><p>{{ spellDetails[spell]?.flavor }}</p><small>{{ spellDetails[spell]?.rules }}</small></button></div></section></div>
<div class="paper-sheet-section"><h3>Other Equipment &amp; Gear</h3><div class="paper-gear-grid"><article v-for="item in otherGear" :key="item.name"><strong>{{ item.name }}</strong><small v-if="item.choice">{{ item.choice }}</small></article></div></div>
<footer class="paper-sheet-footer"><span>Health penalty: <strong>{{ healthPenaltyValue===null?'Defeated':healthPenaltyValue }}</strong></span><span>Mana restore: <strong>+{{ manaRegen }}/round</strong></span></footer>
</section>
<section class="encounter-history-sheet card-surface"><header><h2>Encounter Record</h2><small>Single encounter log</small></header><div v-if="encounter.events.length" class="encounter-record-list"><p v-for="(item,index) in encounter.events" :key="index">{{ item }}</p></div><p v-else class="muted">No encounter events recorded yet.</p></section>
<div class="encounter-page-actions"><button v-if="encounter.status==='ongoing'" class="secondary-button" @click="complete">Complete</button><button v-if="encounter.status==='ongoing'" class="secondary-button" :class="{active:encounter.locked}" @click="toggleLock">{{ encounter.locked?'Locked':'Lock' }}</button><button class="danger-button" @click="remove">Delete</button></div>
</template><section v-else class="empty-state card-surface"><h2>Encounter Not Found</h2><RouterLink class="primary-button" to="/simulator">Back to Rhythm Engine</RouterLink></section>
</main></template>
<style scoped>
.rule-breadcrumb{display:flex;gap:7px;margin-bottom:8px}.rule-breadcrumb a{color:var(--accent-dark);font-weight:800;text-decoration:none}.encounter-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.encounter-heading h1{margin:0}.encounter-heading p{margin:3px 0 0;color:var(--ink-soft)}.round-control{display:grid;grid-template-columns:34px 58px 34px;align-items:center}.round-control button{height:34px}.round-control span{text-align:center}.round-control small{display:block;font-size:8px}.round-control strong{display:block;font-size:20px}.core-abilities-sheet{padding:12px 14px;margin-bottom:10px;border-top:6px solid var(--accent)}.core-abilities-sheet header{display:flex;justify-content:space-between;gap:12px;align-items:baseline}.core-abilities-sheet h2{margin:0}.core-abilities-sheet p{margin:6px 0 9px;color:var(--ink-soft)}.ability-cells{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}.ability-cells>*{display:grid;place-items:center;min-height:58px;border:1px solid var(--line);border-radius:6px;background:var(--paper)}.ability-cells button{color:var(--ink)}.ability-cells button.spent{opacity:.55;text-decoration:line-through}.paper-character-sheet{overflow:hidden;border:1px solid var(--line-dark);border-top:8px solid var(--accent);background:var(--paper);box-shadow:0 7px 24px rgba(0,0,0,.1)}.paper-sheet-header{display:flex;justify-content:space-between;gap:14px;padding:14px;border-bottom:2px solid var(--line-dark);background:var(--paper-2)}.paper-sheet-header h2{margin:2px 0;font-size:27px}.paper-sheet-header p{margin:0;color:var(--ink-soft)}.paper-vitals{display:grid;grid-template-columns:repeat(3,76px);gap:6px}.paper-vitals label{display:grid;gap:3px;text-align:center;font-weight:850}.paper-vitals input,.attack-target-fields input,.damage-line input,.damage-line select{min-width:0;width:100%;padding:7px;border:1px solid var(--line-dark);background:var(--paper);color:var(--ink)}.paper-sheet-section{padding:11px 14px;border-bottom:1px solid var(--line)}.paper-sheet-section h3,.paper-sheet-columns h3{display:flex;align-items:center;gap:8px;margin:0 0 8px;text-transform:uppercase;letter-spacing:.06em;font-size:14px}.paper-sheet-section h3::after,.paper-sheet-columns h3::after{content:'';height:1px;flex:1;background:var(--line-dark)}.paper-stat-row{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}.paper-stat-row.secondary{grid-template-columns:repeat(7,minmax(0,1fr))}.paper-stat-row>*{display:grid;place-items:center;gap:2px;padding:7px 4px;border:1px solid var(--line-dark);border-radius:5px;background:var(--paper);color:var(--ink)}.paper-stat-row strong{font-size:19px}.paper-stat-row span,.paper-stat-row small{font-size:9px}.paper-roll-strip{display:flex;justify-content:space-between;gap:12px;padding:9px 14px;border-bottom:1px solid var(--line);background:var(--accent-wash)}.paper-sheet-columns{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line)}.paper-sheet-columns>section{min-width:0;padding:12px 14px}.paper-sheet-columns>section+section{border-left:1px solid var(--line-dark)}.paper-box-list{display:grid;gap:7px}.paper-entry{display:grid;gap:4px;padding:9px 10px;border:1px solid var(--line-dark);border-top:5px solid var(--accent);border-radius:5px;background:var(--paper);color:var(--ink);text-align:left}.paper-entry header{display:flex;justify-content:space-between;gap:8px;align-items:baseline;border-bottom:1px solid var(--line);padding-bottom:5px}.paper-entry p,.paper-entry small{margin:0;color:var(--ink-soft);line-height:1.4}.paper-entry.weapon{cursor:pointer;border-top-color:#8c4a32}.paper-entry.armor{border-top-color:#526574}.paper-entry.talent{border-top-color:#826126}.paper-entry.spell{border-top-color:#6f4b8c;cursor:pointer}.paper-entry.lore{border-top-color:#446d85;margin-bottom:7px}.weapon-line{display:flex;gap:12px}.attack-target-fields,.damage-line{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin-top:8px}.attack-target-fields label,.damage-line label{display:grid;gap:2px;font-size:9px;font-weight:800}.damage-line>div{display:grid;place-items:center;border:1px solid var(--line);border-radius:5px}.damage-line>button{grid-column:1/-1}.combat-result-strip{display:flex;justify-content:space-between;padding:8px;margin-top:7px;border-radius:5px}.combat-result-strip.good{background:#dcebdc}.combat-result-strip.bad{background:#f1dddd}.paper-skill-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.paper-skill-grid article{display:grid;grid-template-columns:1fr auto;gap:2px;padding:7px;border:1px solid var(--line);border-radius:5px}.paper-skill-grid small{grid-column:1/-1;color:var(--ink-soft)}.paper-gear-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px}.paper-gear-grid article{display:grid;padding:6px;border:1px solid var(--line);border-radius:5px}.paper-sheet-footer{display:flex;justify-content:space-between;padding:10px 14px;background:var(--paper-2)}.encounter-history-sheet{margin-top:10px;padding:12px}.encounter-history-sheet header{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid var(--line);padding-bottom:6px}.encounter-history-sheet h2{margin:0}.encounter-record-list{max-height:230px;overflow:auto}.encounter-record-list p{margin:0;padding:6px 0;border-bottom:1px solid var(--line)}.encounter-page-actions{display:flex;gap:7px;justify-content:flex-end;margin-top:10px}@media(max-width:760px){.encounter-heading,.paper-sheet-header{align-items:stretch;flex-direction:column}.paper-vitals,.paper-stat-row.secondary,.paper-stat-row{grid-template-columns:repeat(3,minmax(0,1fr))}.paper-sheet-columns{grid-template-columns:1fr}.paper-sheet-columns>section+section{border-left:0;border-top:1px solid var(--line-dark)}.ability-cells{grid-template-columns:repeat(2,minmax(0,1fr))}.ability-cells>div:last-child{grid-column:1/-1}.paper-skill-grid{grid-template-columns:1fr 1fr}.paper-gear-grid{grid-template-columns:1fr 1fr}.attack-target-fields,.damage-line{grid-template-columns:1fr}.encounter-page-actions{display:grid}}
</style>
